SELECT count(*) FROM public.title title WHERE EXISTS (SELECT 1 FROM public.cast_info ci, public.link_type lt, public.movie_link ml, public.name n WHERE ci.person_id = n.id AND title.id = ci.movie_id AND ml.linked_movie_id = title.id AND lt.id = ml.link_type_id AND (lt.link = 'references' OR lt.link = 'referenced in' OR lt.link = 'features' OR lt.link = 'featured in') AND n.name_pcode_cf >= 'A' AND n.name_pcode_cf <= 'F' AND title.production_year >= 1980 AND title.production_year <= 2010);
